#!/bin/sh
# Build gcon-graphics-wayland, the Wayland display server:
# ../src/main.c (the protocol reader) over wplat.c (libwayland-client,
# xkbcommon, wayland-cursor; libdecor where found, for title bars where
# the compositor draws none), with gcon's own rasterizer and fonts
# (../raster: outline fonts by stb_truetype, found by fontconfig through
# ../src/fontlinux.c; X's misc-fixed), as the SDL server draws. The
# xdg-shell and xdg-decoration code is generated by wayland-scanner from
# the system's wayland-protocols. Needs a C compiler and those, found by
# pkg-config. Never uses the network. The binary is left in
# ../bin/gcon-graphics-wayland. $CC and $CFLAGS are passed on.
#
#   build.sh          build
#   build.sh -check   only say whether the libraries are found
set -eu
cd "$(dirname "$0")"
CC=${CC:-cc}
deps=../../deps
want="wayland-client wayland-cursor xkbcommon fontconfig"
found() {
	command -v pkg-config >/dev/null 2>&1 && pkg-config --exists $want wayland-protocols wayland-scanner 2>/dev/null
}
if [ "${1:-}" = -check ]; then
	found
	exit
fi
found || { echo "wayland/build.sh: no $want wayland-protocols wayland-scanner (pkg-config): install the development files" >&2; exit 1; }
decor=
if pkg-config --exists libdecor-0 2>/dev/null; then
	decor=libdecor-0
fi
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
sha256() { { sha256sum "$1" 2>/dev/null || shasum -a 256 "$1"; } | awk '{print $1; exit}'; }
grep -v '^#' "$deps/deps.lock" | awk 'index($1, "fixed/") == 1 || $1 == "stb/stb_truetype.h"' |
	while read -r name ver sha url; do
		[ "$(sha256 "$deps/$name")" = "$sha" ] ||
			{ echo "wayland/build.sh: deps/$name does not match deps/deps.lock" >&2; exit 1; }
	done
sh ../raster/bdf2c.sh "$deps"/fixed/*.bdf >"$tmp/fixedfonts.inc"
scanner=$(pkg-config --variable=wayland_scanner wayland-scanner)
protos=$(pkg-config --variable=pkgdatadir wayland-protocols)
for p in stable/xdg-shell/xdg-shell unstable/xdg-decoration/xdg-decoration-unstable-v1; do
	n=$(basename "$p")
	"$scanner" client-header "$protos/$p.xml" "$tmp/$n-client-protocol.h"
	"$scanner" private-code "$protos/$p.xml" "$tmp/$n-protocol.c"
done
mkdir -p ../bin
# shellcheck disable=SC2086 # the flags are lists
$CC -std=c11 -O2 -Wall -Wextra ${CFLAGS:-} -DRFONT_LOOKUP ${decor:+-DWITH_LIBDECOR} \
	-I../src -I../raster -I"$deps/stb" -I"$tmp" $(pkg-config --cflags $want $decor) \
	-o ../bin/gcon-graphics-wayland.new ../src/main.c ../src/xcolors.c wplat.c \
	../raster/raster.c ../raster/rcanvas.c ../raster/rfont.c ../src/fontlinux.c \
	"$tmp/xdg-shell-protocol.c" "$tmp/xdg-decoration-unstable-v1-protocol.c" \
	$(pkg-config --libs $want $decor) -lm
mv ../bin/gcon-graphics-wayland.new ../bin/gcon-graphics-wayland
echo "wayland/build.sh: built bin/gcon-graphics-wayland${decor:+ (with libdecor)}"
